// app/papers/[id]/page.tsx
'use client';

import { createClient } from '@supabase/supabase-js';
import { useEffect, useState } from 'react';
import Link from 'next/link';

export default function PaperDetail({ params }: { params: { id: string } }) {
  const [paper, setPaper] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    );

    const fetchPaper = async () => {
      const { data, error } = await supabase
        .from('papers')
        .select('*')
        .eq('id', params.id)
        .single();

      if (error) {
        console.error('获取论文失败:', error);
      } else {
        setPaper(data);
      }
      setLoading(false);
    };

    fetchPaper();
  }, [params.id]);

  if (loading) return <div className="p-8">加载中...</div>;
  if (!paper) return <div className="p-8">未找到该论文</div>;

  return (
    <div className="max-w-3xl mx-auto p-6">
      <Link href="/" className="text-blue-600 hover:underline mb-4 inline-block">
        ← 返回论文列表
      </Link>
      <h1 className="text-2xl font-bold">{paper.title}</h1>
      <p className="mt-2"><strong>作者：</strong>{paper.author}</p>
      <p className="mt-4"><strong>摘要：</strong></p>
      <p className="mt-2 text-gray-700">{paper.abstract}</p>
      <p className="mt-4">
        <strong>关键词：</strong>
        {paper.keywords?.map((k: string) => (
          <span key={k} className="inline-block bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded mr-2 mt-1">
            {k}
          </span>
        ))}
      </p>
    </div>
  );
}